#!/usr/bin/env sh
set -eu

if [ ! -f .env.previous ]; then
  echo "No .env.previous file was found; nothing to roll back to" >&2
  exit 1
fi

set -a
# Generated by deploy.sh on the production host.
# shellcheck disable=SC1091
. ./.env.previous
set +a

if [ -z "${APP_IMAGE:-}" ]; then
  echo "APP_IMAGE is missing from .env.previous" >&2
  exit 1
fi

echo "Rolling back to ${APP_IMAGE}"
docker pull "$APP_IMAGE"
docker compose up -d --no-build --wait --wait-timeout 60
cp .env.previous .env
echo "Rollback is healthy"
